/* Staged multi-species authoring. The registry is committed only by Save changes. */
let animalSetupDraft=null,animalSetupOriginal='',animalSetupSelected='',animalSetupEditing=null;
const animalSetupGroups=[['breeds','Breeds','e.g. Beetal, Boer'],['lifecycle_stages','Lifecycle stages','e.g. Young, Fattening'],['shed_tags','Shed / stage tags','e.g. Warm-up, Bucks'],['animal_tags','Animal groups','e.g. Breeding, Fattening']];
function animalSetupChanged(){const edit=animalSetupEditing&&EntityRegistryModel.rows(animalSetupDraft,animalSetupEditing.kind).find(r=>r.id===animalSetupEditing.id);return animalSetupDraft&&(JSON.stringify(animalSetupDraft)!==animalSetupOriginal||(edit&&$('#setup-edit-name')&&$('#setup-edit-name').value!==edit.name)||['species','sex_values',...animalSetupGroups.map(g=>g[0])].some(kind=>String($('#setup-add-'+kind)?.value||'').trim()));}
function animalSetupCollect(){let next=structuredClone(animalSetupDraft);for(const kind of [...animalSetupGroups.map(g=>g[0]),'sex_values','species']){const value=$('#setup-add-'+kind)?.value||'';if(value.trim())next=animalSetupApplyAdd(next,kind,value,animalSetupSelected);}if(animalSetupEditing&&$('#setup-edit-name')){const {kind,id}=animalSetupEditing,row=EntityRegistryModel.rows(next,kind).find(r=>r.id===id);EntityRegistryModel.save(next,kind,{...row,name:$('#setup-edit-name').value});}return next;}

bulkAnimalSetup=function(){if(!canEdit())return;closeModal();if(!animalSetupDraft){animalSetupDraft=structuredClone(entityRegistryData());animalSetupOriginal=JSON.stringify(animalSetupDraft);animalSetupSelected=animalSetupDraft.records.species.find(r=>r.active)?.id||'';}renderAnimalSetup();document.querySelector('#main')?.scrollTo?.({top:0});};
function renderAnimalSetup(){
 const types=EntityRegistryModel.rows(animalSetupDraft,'species').filter(r=>r.active),selected=types.find(r=>r.id===animalSetupSelected)||types[0];animalSetupSelected=selected?.id||'';
 $('#main').innerHTML=`<section class="animal-setup-page"><div class="setup-topbar"><div><button class="setup-back" onclick="animalSetupBack()">← Business records</button><h1>Animal setup</h1><p>Add animal types and their lists together.</p></div><div class="actions"><span id="setup-save-state">${animalSetupChanged()?'Unsaved changes':'All changes saved'}</span><button class="primary" onclick="animalSetupCommit()">Save changes</button></div></div><div id="setup-error" role="alert" class="error"></div><div class="setup-layout"><nav class="setup-types" aria-label="Animal types"><div class="setup-section-heading"><h2>Animal types</h2><span>${types.length}</span></div>${types.map(r=>`<button class="setup-type ${r.id===animalSetupSelected?'active':''}" onclick="animalSetupSelect('${r.id}')"><span>${esc(r.name)}</span><span>›</span></button>`).join('')}<form class="setup-add-types" onsubmit="event.preventDefault();animalSetupAdd('species')"><label for="setup-add-species">Add animal types</label><input id="setup-add-species" placeholder="e.g. Goat, Sheep" autocomplete="off"><button type="submit">+ Add types</button></form></nav><div class="setup-detail">${selected?`<div class="setup-detail-heading"><div><span class="eyebrow">Animal type</span><h2>${esc(selected.name)}</h2></div><div class="actions"><button onclick="animalSetupEdit('species','${selected.id}')">Rename</button><button class="setup-quiet" onclick="animalSetupArchive('species','${selected.id}')">Archive</button></div></div><div id="setup-edit-species">${animalSetupEditField('species')}</div><div class="setup-list-grid">${animalSetupGroups.map(([kind,title,placeholder])=>animalSetupGroup(kind,title,placeholder)).join('')}</div>`:'<div class="empty">Add an animal type to start.</div>'}<section class="setup-shared"><div><h2>Gender / sex</h2><p>Shared across animal types</p></div>${animalSetupGroup('sex_values','','e.g. Female, Male')}</section></div></div></section>`;
}
function animalSetupGroup(kind,title,placeholder){const rows=EntityRegistryModel.rows(animalSetupDraft,kind).filter(r=>r.active&&(kind==='sex_values'||r.parentId===animalSetupSelected));return `<section class="setup-list"><div class="setup-section-heading">${title?`<h3>${title}</h3><span>${rows.length}</span>`:''}</div><div class="setup-chips">${rows.map(r=>`<div class="setup-chip"><button aria-label="Edit ${esc(r.name)} ${esc(title||'gender / sex')}" onclick="animalSetupEdit('${kind}','${r.id}')">${esc(r.name)}</button><button class="setup-chip-remove" aria-label="Archive ${esc(r.name)} ${esc(title||'gender / sex')}" onclick="animalSetupArchive('${kind}','${r.id}')">×</button></div>`).join('')||'<span class="setup-empty">None added</span>'}</div>${animalSetupEditField(kind)}<form class="setup-add-row" onsubmit="event.preventDefault();animalSetupAdd('${kind}')"><input id="setup-add-${kind}" aria-label="Add ${title||'gender / sex values'}" placeholder="${placeholder}" autocomplete="off"><button type="submit" aria-label="Add ${title||'gender / sex values'}">+</button></form></section>`;}
function animalSetupEditField(kind){if(animalSetupEditing?.kind!==kind)return '';const row=EntityRegistryModel.rows(animalSetupDraft,kind).find(r=>r.id===animalSetupEditing.id);return `<form class="setup-edit-row" onsubmit="event.preventDefault();animalSetupRename()"><input id="setup-edit-name" aria-label="Edit record name" value="${esc(row.name)}"><button type="submit">Apply</button><button type="button" onclick="animalSetupCancelEdit()">Cancel</button></form>`;}
function animalSetupSelect(id){try{animalSetupDraft=animalSetupCollect();animalSetupSelected=id;animalSetupEditing=null;renderAnimalSetup();}catch(e){$('#setup-error').textContent=e.message;}}
function animalSetupApplyAdd(data,kind,names,parentId){const next=structuredClone(data);for(const name of String(names).split(',').map(s=>s.trim()).filter(Boolean)){const existing=EntityRegistryModel.rows(next,kind).find(r=>r.active&&r.name.toLowerCase()===name.toLowerCase()&&(!EntityRegistryModel.def(kind).parent||r.parentId===parentId));if(!existing)EntityRegistryModel.save(next,kind,{name,parentId});}return next;}
function animalSetupAdd(kind){if(!canEdit())return;try{const input=$('#setup-add-'+kind),names=input.value.trim();if(!names)return;animalSetupDraft=animalSetupCollect();if(kind==='species')animalSetupSelected=animalSetupDraft.records.species.find(r=>r.active&&r.name.toLowerCase()===names.split(',')[0].trim().toLowerCase())?.id||animalSetupSelected;animalSetupEditing=null;renderAnimalSetup();}catch(e){$('#setup-error').textContent=e.message;}}
function animalSetupEdit(kind,id){try{animalSetupDraft=animalSetupCollect();animalSetupEditing={kind,id};renderAnimalSetup();$('#setup-edit-name')?.focus();}catch(e){$('#setup-error').textContent=e.message;}}
function animalSetupCancelEdit(){const editing=animalSetupEditing;try{animalSetupEditing=null;animalSetupDraft=animalSetupCollect();renderAnimalSetup();}catch(e){animalSetupEditing=editing;$('#setup-error').textContent=e.message;}}
function animalSetupRename(){if(!canEdit())return;try{animalSetupDraft=animalSetupCollect();animalSetupEditing=null;renderAnimalSetup();}catch(e){$('#setup-error').textContent=e.message;}}
function animalSetupArchive(kind,id){if(!canEdit())return;try{const next=animalSetupCollect();EntityRegistryModel.archive(next,kind,id);animalSetupDraft=next;animalSetupEditing=null;renderAnimalSetup();}catch(e){$('#setup-error').textContent=e.message;}}
function animalSetupCommit(){if(!canEdit())return;try{if(JSON.stringify(entityRegistryData())!==animalSetupOriginal)throw Error('The records changed while this setup was open. Your draft is kept. Return to Business records, discard this draft and reopen setup.');const next=animalSetupCollect();state.entityRegistry=next;animalSetupDraft=structuredClone(next);record('Saved animal setup');animalSetupOriginal=JSON.stringify(animalSetupDraft);animalSetupEditing=null;renderAnimalSetup();toast('Animal setup saved');return true;}catch(e){$('#setup-error').textContent=e.message;return false;}}
function animalSetupBack(){if(animalSetupChanged()){modal('Leave animal setup?',`<p>Your changes have not been saved.</p><div class="actions"><button onclick="closeModal()">Keep editing</button><button onclick="if(animalSetupCommit()){closeModal();animalSetupDraft=null;renderItems()}">Save and leave</button><button onclick="animalSetupDraft=null;closeModal();renderItems()">Discard changes</button></div>`);return;}animalSetupDraft=null;renderItems();}
window.addEventListener('beforeunload',e=>{if(animalSetupChanged()){e.preventDefault();e.returnValue='';}});
